(()=>{const photos={'cmcartonaria':'data:image/jpeg;base64,','anaperrefotografia':'data:image/jpeg;base64,','boxphotoefilms':'data:image/jpeg;base64,','dcdesign':'data:image/jpeg;base64,','donamirinha':'data:image/jpeg;base64,','kedproducoes':'data:image/jpeg;base64,','debutantezen':'data:image/jpeg;base64,','ingridfreitasbeauty':'data:image/jpeg;base64,','carollcardozo':'data:image/jpeg;base64,','graficaamltda':'data:image/jpeg;base64,','graficaam':'data:image/jpeg;base64,','gabriellamachadomakeup':'data:image/jpeg;base64,','amoresfotografia':'data:image/jpeg;base64,','fricottepersonalizados':'data:image/jpeg;base64,','lurodrigues':'data:image/jpeg;base64,'};const normalize=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/gi,'').toLowerCase();const apply=()=>document.querySelectorAll('.supplier-card').forEach(card=>{const title=card.querySelector('h3')?.textContent?.trim()||'';const source=photos[normalize(title)];const logo=card.querySelector('.supplier-logo');if(!source||!logo)return;logo.classList.add('has-photo','has-supplier-logo');let image=logo.querySelector('.supplier-photo');if(!image){image=document.createElement('img');image.className='supplier-photo';logo.prepend(image)}image.src=source;image.alt='Logo de '+title});window.addEventListener('load',()=>{apply();setTimeout(apply,1500)});const grid=document.querySelector('#supplierGrid');if(grid)new MutationObserver(apply).observe(grid,{childList:true,subtree:true})})();